return {
  json: {
    ...$json,
    threadId: String($json.thread_id ?? ''),
    groupName: String($json.group_name ?? ''),
    senderId: String($json.sender_id ?? ''),
    senderName: String($json.sender_name ?? ''),
    messageText: String($json.message_text ?? ''),
    messageTs: String($json.message_ts ?? ''),
  },
};

const normalizeText = (value) => String(value ?? '').trim();
const normalizeNumber = (value) => {
  const num = Number(value ?? 0);
  return Number.isFinite(num) ? num : 0;
};
const normalizeDate = (value) => {
  const text = normalizeText(value);
  return /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : '';
};
const normalizeTime = (value) => {
  const text = normalizeText(value);
  return /^\d{2}:\d{2}$/.test(text) ? text : '';
};
const asArray = (value) => Array.isArray(value) ? value : [];

const finishReason = $json?.finishReason ?? '';
const parts = $json?.content?.parts ?? [];
const textPart = parts.find((part) => typeof part?.text === 'string')?.text ?? '';

let clean = textPart
  .replace(/^```json\s*/i, '')
  .replace(/^```/i, '')
  .replace(/```$/i, '')
  .trim();

const firstBrace = clean.indexOf('{');
const lastBrace = clean.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace > firstBrace) {
  clean = clean.slice(firstBrace, lastBrace + 1);
}

let data;
try {
  data = JSON.parse(clean);
} catch (error) {
  throw new Error(`Gemini did not return valid JSON. Finish reason: ${finishReason}. Raw output: ${clean}`);
}

const attendanceEntries = asArray(data.attendance_entries).map((entry) => ({
  employee_name: normalizeText(entry?.employee_name),
  work_date: normalizeDate(entry?.work_date),
  shift: normalizeText(entry?.shift),
  start_time: normalizeTime(entry?.start_time),
  end_time: normalizeTime(entry?.end_time),
  hours: normalizeNumber(entry?.hours),
  overtime_hours: normalizeNumber(entry?.overtime_hours),
  site: normalizeText(entry?.site),
  task: normalizeText(entry?.task),
  status: normalizeText(entry?.status),
  note: normalizeText(entry?.note),
})).filter((entry) => entry.employee_name || entry.work_date || entry.site || entry.task || entry.hours || entry.overtime_hours);

const notes = asArray(data.notes).map((note) => normalizeText(note)).filter(Boolean);
const documentType = normalizeText(data.document_type) || 'other';
let queueStatus = 'ignored';
if (documentType === 'attendance' && attendanceEntries.length > 0) {
  queueStatus = 'done';
} else if (documentType === 'attendance' || Boolean(data.needs_human_review)) {
  queueStatus = 'needs_review';
}

return {
  json: {
    ...$input.item.json,
    finish_reason: normalizeText(finishReason),
    summary: normalizeText(data.summary),
    document_type: documentType,
    confidence: normalizeNumber(data.confidence),
    needs_human_review: Boolean(data.needs_human_review),
    attendance_entries: attendanceEntries,
    main_material_entries: [],
    sub_material_entries: [],
    attendance_count: attendanceEntries.length,
    main_material_count: 0,
    sub_material_count: 0,
    notes,
    status: queueStatus,
    processed_at: new Date().toISOString(),
    attendance_json: JSON.stringify(attendanceEntries),
    appscript_action: {
      mode: 'route_attendance',
      targets: ['ChamCong'],
    },
    raw_ai_json: clean,
  },
};

const pickQueueFields = (input, overrides = {}) => ({
  id: input.id,
  queue_key: String(input.queue_key ?? ''),
  thread_id: String(input.thread_id ?? ''),
  group_name: String(input.group_name ?? ''),
  sender_id: String(input.sender_id ?? ''),
  sender_name: String(input.sender_name ?? ''),
  message_text: String(input.message_text ?? ''),
  message_ts: String(input.message_ts ?? ''),
  raw_message_json: String(input.raw_message_json ?? ''),
  status: String(input.status ?? 'pending'),
  retry_count: Number(input.retry_count ?? 0),
  last_error: String(input.last_error ?? ''),
  processed_at: input.processed_at ?? null,
  summary: String(input.summary ?? ''),
  attendance_json: String(input.attendance_json ?? ''),
  needs_human_review: Boolean(input.needs_human_review),
  confidence: Number(input.confidence ?? 0),
  appscript_response: String(input.appscript_response ?? ''),
  ...overrides,
});

if ($json.document_type !== 'attendance' || !Array.isArray($json.attendance_entries) || $json.attendance_entries.length === 0) {
  return {
    json: pickQueueFields($json, {
      appscript_response: JSON.stringify({ skipped: true, reason: 'non-attendance-or-empty' }),
    }),
  };
}

const url = 'https://script.google.com/macros/s/AKfycbyzC-qw38puhlm5btycJs6ohYXArbRWBF7j70o0zU4MeHCWaoKjXM4BN4XXZXveHsgD/exec';
const response = await helpers.httpRequest({
  method: 'POST',
  url,
  headers: {
    'Content-Type': 'application/json',
  },
  body: $json,
  json: true,
});

return {
  json: pickQueueFields($json, {
    appscript_response: typeof response === 'string' ? response : JSON.stringify(response),
  }),
};
